WITH male_admissions AS (SELECT a.hadm_id FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 94 AND a.admission_type = 'Ischemic stroke'), male_discharges AS (SELECT l.value AS glucose_level, m.hadm_id FROM labevents l JOIN male_admissions m ON l.subject_id = m.hadm_id WHERE l.itemid = 151055) SELECT (percentile_cont(0.75) within GROUP (ORDER BY glucose_level) - percentile_cont(0.25) within GROUP (ORDER BY glucose_level)) AS interquartile_range FROM male_discharges;